package modules

import (
	"fmt"
	"strings"

	"github.com/zapstiko/xsshunts/browser"
	"github.com/zapstiko/xsshunts/csp"
	"github.com/zapstiko/xsshunts/detection"
	"github.com/zapstiko/xsshunts/logger"
	"github.com/zapstiko/xsshunts/models"
	"github.com/zapstiko/xsshunts/payloads"
	"github.com/zapstiko/xsshunts/utils"
)

// RunCSPAnalysis detects the target's Content-Security-Policy, reports weaknesses
// and applicable bypass techniques, then tests generated bypass payloads against
// GET/DOM parameters. Findings are recorded only when a dialog is confirmed.
func RunCSPAnalysis(sess *browser.Session, parameters []*models.Parameter, cfg *models.ScanConfig,
	log *logger.Logger, waf *detection.WAFManager) []*models.XSSFinding {

	response, err := sess.Goto(cfg.TargetURL)
	if err != nil {
		if log != nil {
			log.Debug(fmt.Sprintf("CSP analysis could not load target: %s", utils.CleanErrorText(err.Error())))
		}
		return nil
	}
	sess.WaitNetworkIdle(3000)

	html, _ := sess.Content()
	headers := map[string]string{}
	status := 200
	if response != nil {
		headers, _ = response.AllHeaders()
		status = response.Status()
	}
	if waf != nil && response != nil && cfg != nil {
		waf.HandleResponse(status, headers, html, cfg)
	}

	policy := csp.Parse(headers, html)
	analysis := csp.Analyze(policy)
	reportCSPAnalysis(log, analysis)

	if !analysis.Enforced || analysis.Unrestricted {
		return nil
	}

	includeInline := !cfg.HasModule("get")
	bypassPayloads := csp.BypassPayloads(analysis, includeInline)
	if len(bypassPayloads) == 0 {
		if log != nil {
			log.Info("CSP: no executable bypass payload derived from this policy")
		}
		return nil
	}

	var targetParams []*models.Parameter
	seen := map[string]bool{}
	for _, param := range parameters {
		if param.Location != "GET" && param.Location != "DOM" {
			continue
		}
		actionURL := param.ActionURL
		if actionURL == "" {
			actionURL = cfg.TargetURL
		}
		key := strings.ToLower(actionURL) + "|" + strings.ToLower(param.ParamName)
		if seen[key] {
			continue
		}
		seen[key] = true
		param.ActionURL = actionURL
		targetParams = append(targetParams, param)
	}

	if len(targetParams) == 0 {
		if log != nil {
			log.Warning("CSP: bypass payloads require a GET/DOM parameter, but none were discovered")
		}
		return nil
	}

	findings := []*models.XSSFinding{}
	for _, param := range targetParams {
		if log != nil {
			log.StartParamTest(param.ParamName, "CSP", "csp_bypass")
		}
		for _, bypass := range bypassPayloads {
			if log != nil {
				log.Trying("[CSP] "+bypass.Name, bypass.Payload)
			}
			delayMin, delayMax := cfg.GetDelays()
			utils.DelayMs(delayMin, delayMax)

			pocURL := utils.BuildPayloadedURL(param.ActionURL, param.ParamName, bypass.Payload)
			payloadData := &payloads.PayloadData{
				Key:           bypass.Key,
				Name:          "[CSP] " + bypass.Name,
				Payload:       bypass.Payload,
				DialogType:    bypass.DialogType,
				ExpectedValue: bypass.ExpectedValue,
				CheckForMatch: 0,
			}

			outcome := runNavProbe(sess, pocURL, payloadData, cfg, waf, log)
			confirmed := outcome.XSScan == 1
			confidence := detection.CalculateConfidence(outcome.XSScan, 0)

			if log != nil {
				log.TestBlock(logger.TestBlockOpts{
					Method:      "CSP",
					ParamName:   param.ParamName,
					Context:     "csp_bypass",
					PayloadName: "[CSP] " + bypass.Name,
					PayloadStr:  bypass.Payload,
					RequestDesc: "GET " + pocURL,
					Confidence:  confidence,
					IsXSS:       confirmed,
				})
			}

			if confirmed {
				finding := models.NewXSSFinding()
				finding.Endpoint = param.ActionURL
				finding.ParamName = param.ParamName
				finding.Context = "csp_bypass"
				finding.PayloadName = "[CSP] " + bypass.Name
				finding.PayloadKey = "csp_" + bypass.Key
				finding.PayloadValue = bypass.Payload
				finding.RequestMethod = param.Location
				finding.RequestURL = pocURL
				finding.XSS = 1
				finding.Confidence = confidence
				finding.XSScan = 1
				finding.ResponseURL = outcome.ResponseURL
				finding.ResponseHeaders = outcome.ResponseHeaders
				finding.Text = outcome.Text
				finding.CreatedAt = utils.CurrentTime()
				finding.ProofOfConcept = pocURL
				findings = append(findings, finding)
				if log != nil {
					log.Debug(fmt.Sprintf("CSP bypass confirmed for '%s' using %s", param.ParamName, bypass.Name))
				}
				break
			}

			delayMin, delayMax = cfg.GetDelays()
			utils.DelayMs(delayMin, delayMax)
		}
	}
	return findings
}

func reportCSPAnalysis(log *logger.Logger, analysis *csp.Analysis) {
	if log == nil || log.Silent {
		return
	}
	if !analysis.Present {
		log.Info("CSP analysis: no Content-Security-Policy detected")
		return
	}
	if analysis.ReportOnlyOnly {
		log.Warning("CSP analysis: Content-Security-Policy-Report-Only detected (not enforced)")
	} else {
		log.Info("CSP analysis: enforced Content-Security-Policy detected")
	}
	if analysis.ScriptDirective != "" {
		log.Info(fmt.Sprintf("  effective script directive: %s (%s)",
			analysis.ScriptDirective, strings.Join(analysis.ScriptSources, " ")))
	}
	for _, issue := range analysis.Issues {
		line := fmt.Sprintf("  CSP [%s] %s: %s", issue.Severity, issue.Directive, issue.Message)
		if issue.Severity == "high" || issue.Severity == "medium" {
			log.Warning(line)
		} else {
			log.Info(line)
		}
	}
	if len(analysis.Techniques) > 0 {
		log.Info(fmt.Sprintf("  applicable bypass technique(s): %d", len(analysis.Techniques)))
		for _, technique := range analysis.Techniques {
			log.Success("    - " + technique.Name)
			log.Debug("      " + technique.Description)
			if len(technique.Payloads) > 0 {
				log.Debug("      example: " + technique.Payloads[0])
			}
		}
	}
}
